import {Port,materials} from '../../core/index.js';import {portQuaternion} from '../../modeling/parts.js';import {THREE,box} from './geometry.js';import {spec} from './dimensions.js';
export function grove(host){const frame=new THREE.Group();frame.name='Original U001-B red actual4P receiving assembly';frame.position.fromArray(spec.grove.position);frame.quaternion.copy(portQuaternion('bottom'));host.body.add(frame);const red=materials.plastic(0xab2c3a,{roughness:.7}),tin=materials.metal(0xb4b8a6,{roughness:.45}),parts=[],walls=[],contacts=[],returns=[],feet=[],tails=[],b=(size,p,name,mat=red)=>{const o=box(frame,size,p,mat,'ENV-II Grove '+name);parts.push(o);return o;};for(const sign of[-1,1]){walls.push(b([.7,7.6,5.2],[sign*4.65,-3.8,0],'actual side receiving wall'));walls.push(b([.65,7.6,.65],[sign*3.98,-3.8,2.25],'actual upper retaining rail'));}const floor=b([8.6,7.6,.6],[0,-3.8,-2.3],'real dielectric floor'),back=b([8.6,.7,4.6],[0,-7.25,.3],'actual deep dielectric insertion stop'),latch=b([3.8,1.3,.5],[0,-4.7,2.25],'physical retaining bridge'),seat=b([8.6,1.2,.8],[0,-8.1,-2.2],'real deep carrier support meetsPCB');for(let i=0;i<4;i++){const x=(i-1.5)*2;contacts.push(b([.42,5.8,.42],[x,-4,-.6],'real retained contact '+(i+1),tin));returns.push(b([.42,.6,2.2],[x,-7.2,-1.5],'real conductor return '+(i+1),tin));feet.push(b([.42,1.4,.42],[x,-7.8,-2.4],'actual solder foot '+(i+1),tin));tails.push(b([.42,.42,1.8],[x,-8.3,-3.1],'actual through-board retained tail '+(i+1),tin));}const port=host.add(new Port({id:'grove',label:'Original ENV-II J1 · red HY2.0-4P',connector:'grove',position:spec.grove.position,quaternion:portQuaternion('bottom'),hitSize:[10,1,5.2],pinGrid:{cols:4,rows:1,pitch:2,center:[0,-.6],order:col=>col+1},pins:spec.grove.pins.map((name,i)=>({n:i+1,name})),meta:{role:'visual-connector',face:'bottom',numbering:'Literal original J1/rear label SCL,SDA,VCC,GND;no automatic wire color/electrical routing.',scope:'Actual4contact receiving/cable mechanics only,no sensor values,address,I2C,power or firmware.'}}));return{frame,parts,walls,floor,back,latch,seat,contacts,returns,feet,tails,port};}
